# ── Multi-agent registry lookup ──────────────────────────────────────────────
# Maps bot_id (lowercase) → its CVE list. Add new agent frameworks here.
_AGENT_CVE_REGISTRIES: dict[str, list[dict[str, Any]]] = {
    "openclaw": _OPENCLAW_CVE_REGISTRY,
    "hermes": _HERMES_CVE_REGISTRY,
}

# ── Per-agent CVE pipeline config (single source of truth) ────────────────────
# Every wrapped agent gets a COMPLETELY SEPARATE, PARALLEL CVE pipeline.  There
# is no shared processing between agents: each agent has its own upstream GHSA
# advisory source, its own registry list (above), its own synthetic-id prefix,
# its own website section markers, and its own Telegram alert title.  Wrapping a
# NEW agent = add ONE entry here → it automatically gets a fully independent
# pipeline (detection → dedup vs its OWN list → under_review auto-register →
# its own alert → its own website section).  The runtime scheduler
# (daily_cve_report.py) and the CI sync (scripts/sync-cve-registry.py) BOTH loop
# over this config; neither hardcodes a per-agent special-case.
#
# ghsa_repo_env / ghsa_repo_default — the agent's OWN GitHub Security-Advisory
#   feed.  OpenClaw publishes advisories at ``openclaw/openclaw``.  Hermes's real
#   upstream is ``nousresearch/hermes-agent`` (the image AgentShroud wraps); it
#   currently publishes ZERO advisories, so the Hermes check runs and reports
#   "0 new" honestly — the pipeline is live and ready when advisories appear.
# id_prefix — synthetic AgentShroud ref prefix (NEVER a real CVE/GHSA id).
# alert_title — the agent-specific Telegram alert heading.
_AGENT_CVE_SOURCES: dict[str, dict[str, str]] = {
    "openclaw": {
        "display_name": "OpenClaw",
        "ghsa_repo_env": "AGENTSHROUD_OPENCLAW_GHSA_REPO",
        "ghsa_repo_default": "openclaw/openclaw",
        "id_prefix": "ASH-OCLAW",
        "alert_title": "OpenClaw",
    },
    "hermes": {
        "display_name": "Hermes Agent",
        "ghsa_repo_env": "AGENTSHROUD_HERMES_GHSA_REPO",
        # Real upstream: the wrapped image is ``nousresearch/hermes-agent``.
        # Verified 2026-07-16: repo exists (HTTP 200), 0 published advisories.
        "ghsa_repo_default": "nousresearch/hermes-agent",
        "id_prefix": "ASH-HERMES",
        "alert_title": "Hermes Agent",
    },
}


def get_agent_cve_source(bot_id: str) -> dict[str, str]:
    """Return the CVE-pipeline config for *bot_id* (raises KeyError if unknown).

    Args:
        bot_id: The agent/bot identifier (e.g. ``"openclaw"``, ``"hermes"``).

    Returns:
        The config dict with keys: display_name, ghsa_repo_env,
        ghsa_repo_default, id_prefix, alert_title.

    Raises:
        KeyError: If *bot_id* is not a registered agent.
    """
    return _AGENT_CVE_SOURCES[bot_id]


def get_agent_ghsa_repo(bot_id: str) -> str:
    """Return the resolved GitHub advisory repo slug for *bot_id*.

    Honors the per-agent environment override (``ghsa_repo_env``) so operators
    can point an agent at a different fork/mirror without a code change; falls
    back to the committed default otherwise.

    Args:
        bot_id: The agent/bot identifier.

    Returns:
        An ``owner/name`` GitHub repo slug.

    Raises:
        KeyError: If *bot_id* is not a registered agent.
    """
    import os

    src = _AGENT_CVE_SOURCES[bot_id]
    return os.environ.get(src["ghsa_repo_env"], src["ghsa_repo_default"])


# ── Backward-compatible public aliases ───────────────────────────────────────
# AGENT_CVE_REGISTRY — imported by daily_cve_report.py and other consumers
# that predate multi-agent support.  Points at the OpenClaw list unchanged.
AGENT_CVE_REGISTRY = _OPENCLAW_CVE_REGISTRY
HERMES_CVE_REGISTRY = _HERMES_CVE_REGISTRY


def list_cve_agents() -> list[str]:
    """Return the list of registered agent bot IDs with CVE coverage.

    Returns:
        List of bot_id strings (e.g. ["openclaw", "hermes"]).
    """
    return list(_AGENT_CVE_REGISTRIES.keys())


def get_agent_cve_summary(bot_id: str = "openclaw") -> dict[str, Any]:
    """Return a summary of the advisory registry for the specified agent.

    Counts are stated honestly: this registry tracks *advisories* (not "CVEs").
    Each entry carries a synthetic ``id`` plus a ``ghsa_id`` / ``cve_id`` that is
    populated only when a real upstream match is verified (else ``None``).

    Args:
        bot_id: The agent/bot identifier.  Defaults to ``"openclaw"`` for
                backward compatibility with callers that predate multi-agent
                support.  Pass ``"hermes"`` for the Hermes agent registry.

    Returns:
        Dict with keys:
          wrapped_agent, total_cves (deprecated alias of advisories_tracked),
          advisories_tracked, ghsa_matched, cve_matched, pending_review,
          by_status, by_severity, cves.

    Raises:
        KeyError: If *bot_id* is not found in the registry.
    """
    registry = _AGENT_CVE_REGISTRIES[bot_id]
    total = len(registry)
    by_status: dict[str, int] = {status: 0 for status in MITIGATION_STATUS}
    by_severity: dict[str, int] = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}
    ghsa_matched = 0
    cve_matched = 0
    pending_review = 0
    for cve in registry:
        by_status[cve["status"]] = by_status.get(cve["status"], 0) + 1
        by_severity[cve["severity"]] = by_severity.get(cve["severity"], 0) + 1
        has_ghsa = bool(cve.get("ghsa_id"))
        has_cve = bool(cve.get("cve_id"))
        if has_ghsa:
            ghsa_matched += 1
        if has_cve:
            cve_matched += 1
        if not has_ghsa and not has_cve:
            pending_review += 1

    return {
        "wrapped_agent": WRAPPED_AGENT if bot_id == "openclaw" else bot_id.capitalize(),
        # total_cves is retained as a backward-compatible alias but the honest
        # label is advisories_tracked — these are tracked advisories, not CVEs.
        "total_cves": total,
        "advisories_tracked": total,
        "ghsa_matched": ghsa_matched,
        "cve_matched": cve_matched,
        "pending_review": pending_review,
        "by_status": by_status,
        "by_severity": by_severity,
        "cves": registry,
    }
